Tooltip>);\r\n\r\nexport default EvaluationDetailTooltip;","import React, { PureComponent, Fragment } from 'react';\r\nimport { sumBy, meanBy } from 'lodash';\r\nimport moment from 'moment';\r\nimport { DateFormat } from '../../constants';\r\n\r\nexport default class HRM extends PureComponent {\r\n    renderAttendance = (attendace, index) => {\r\n        return (\r\n            <tr key={attendace.month + attendace.year}>\r\n                <td className=\"text-center\">{attendace.month}/{attendace.year}</td>\r\n                <td className=\"text-center\">{attendace.missingCheckInCheckOut}</td>\r\n                <td className=\"text-center\">{attendace.lateIn}</td>\r\n                <td className=\"text-center\">{attendace.earlyOut}</td>\r\n                <td className=\"text-center\">{attendace.unpaidLeave}</td>\r\n                <td className=\"text-center\">{attendace.unplanAnnualLeave}</td>\r\n                <td className=\"text-center\">{this.displayTime(attendace.averageWorkingHours)}</td>\r\n                <td className=\"text-center\">{this.displayTime(attendace.overtime)}</td>\r\n                {\r\n                    index === 0 &&\r\n                    <td className=\"text-center\" rowSpan={this.props.hrm.attendances.length + 1}>\r\n                        {this.props.hrm.toeic &&\r\n                            <Fragment>\r\n                                <div>\r\n                                    <strong>{this.props.hrm.toeic.toeicScore}</strong>\r\n                                </div>\r\n                                {this.props.hrm.toeic.examDate &&\r\n                                    <div>\r\n                                        ({moment(this.props.hrm.toeic.examDate).format(DateFormat)})\r\n                                    </div>\r\n                                }\r\n                            </Fragment>\r\n                        }\r\n                    </td>\r\n                }\r\n            </tr>\r\n        );\r\n    };\r\n\r\n    displayTime = value => {\r\n        if (!value) {\r\n            return '0h0\\'';\r\n        }\r\n\r\n        const hours = Math.floor(value);\r\n        const hoursString = hours.toString().padStart(2, '0');\r\n        const minutes = Math.round((value - hours) * 60).toString().padStart(2, '0');\r\n\r\n        return `${hoursString !== '00' ? hoursString + 'h' : ''}${minutes}'`;\r\n    };\r\n\r\n    render() {\r\n        return (\r\n            <table className=\"table table-bordered table-striped hrm-table\">\r\n                <thead>\r\n                    <tr>\r\n                        <th>Month</th>\r\n                        <th>Missing Check In/Out</th>\r\n                        <th>Late In</th>\r\n                        <th>Early Out</th>\r\n                        <th>Unpaid Leave</th>\r\n                        <th>Unpaid Annual Leave</th>\r\n                        <th>Average Working Hours</th>\r\n                        <th>Overtime</th>\r\n                        <th>TOEIC Score</th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n                    {this.props.hrm.attendances.map(this.renderAttendance)}\r\n                    <tr className=\"hrm-total\">\r\n                        <td className=\"text-center\">Total</td>\r\n                        <td className=\"text-center\">{sumBy(this.props.hrm.attendances, 'missingCheckInCheckOut')}</td>\r\n                        <td className=\"text-center\">{sumBy(this.props.hrm.attendances, 'lateIn')}</td>\r\n                        <td className=\"text-center\">{sumBy(this.props.hrm.attendances, 'earlyOut')}</td>\r\n                        <td className=\"text-center\">{sumBy(this.props.hrm.attendances, 'unpaidLeave')}</td>\r\n                        <td className=\"text-center\">{sumBy(this.props.hrm.attendances, 'unplanAnnualLeave')}</td>\r\n                        <td className=\"text-center\">{this.displayTime(meanBy(this.props.hrm.attendances, 'averageWorkingHours'))}</td>\r\n                        <td className=\"text-center\">{this.displayTime(sumBy(this.props.hrm.attendances, 'overtime'))}</td>\r\n                    </tr>\r\n                </tbody>\r\n            </table>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\nimport { DateFormat } from '../../constants';\r\n\r\nexport default class Description extends PureComponent {\r\n    render() {\r\n        return (\r\n            <div className=\"info-rate\">\r\n                <div className=\"user-info\">\r\n                    <img src={this.props.employeeInfo.avatar} alt=\"avatar\" className=\"avatar\" />\r\n                    <ul>\r\n                        <li className=\"info\">\r\n                            <span className=\"label\">Full Name:</span>\r\n                            <span className=\"info-text\">{this.props.employeeInfo.fullName}</span>\r\n                        </li>\r\n                        <li className=\"info\">\r\n                            <span className=\"label\">Nick Name:</span>\r\n                            <span className=\"info-text\">{this.props.employeeInfo.nickName}</span>\r\n                        </li>\r\n                        <li className=\"info\">\r\n                            <span className=\"label\">Joined Day:</span>\r\n                            <span className=\"info-text\">{this.props.employeeInfo.joinedDate.format(DateFormat)}</span>\r\n                        </li>\r\n                        <li className=\"info\">\r\n                            <span className=\"label\">Team:</span>\r\n                            <span className=\"info-text\">{this.props.employeeInfo.groupName}</span>\r\n                        </li>\r\n                        <li className=\"info\">\r\n                            <span className=\"label\">Job Title:</span>\r\n                            <span className=\"info-text\">{this.props.employeeInfo.jobTitle}</span>\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n\r\n                <div className=\"rate-information\">\r\n                    <div className=\"rate-item\">\r\n                        <div className=\"rate-star\">\r\n                            <span>Poor: 1 </span>\r\n                            <div className=\"star-block\">\r\n                                <i className=\"fa fa-star\" />\r\n                            </div>\r\n                        </div>\r\n                        <div className=\"rate-description\">Unsatisfactory: Performance was consistently below expectations.\r\n                            Poor quality of work, frequently needs rework. Significant improvement is needed.</div>\r\n                    </div>\r\n                    <div className=\"rate-item\">\r\n                        <div className=\"rate-star\">\r\n                            <span>Below Average: 2</span>\r\n                            <div className=\"star-block\">\r\n                                <i className=\"fa fa-star\" /><i className=\"fa fa-star\" />\r\n                            </div>\r\n                        </div>\r\n                        <div className=\"rate-description\">Improvement needed: Performance did not consistently meet expectations.\r\n                            Did not generally contribute extra effort or energy. An improvement plan is needed.\r\n                            </div>\r\n                    </div>\r\n                    <div className=\"rate-item\">\r\n                        <div className=\"rate-star\">\r\n                            <span>Sastisfactory: 3</span>\r\n                            <div className=\"star-block\">\r\n                                <i className=\"fa fa-star\" /><i className=\"fa fa-star\" /><i className=\"fa fa-star\" />\r\n                            </div>\r\n                        </div>\r\n                        <div className=\"rate-description\">\r\n                            Meets expectations:\r\n                            Solid performance with a good quality of work, at times possibly exceeding expectations and contributing additional value.</div>\r\n                    </div>\r\n                    <div className=\"rate-item\">\r\n                        <div className=\"rate-star\">\r\n                            <span>Good: 4</span>\r\n                            <div className=\"star-block\">\r\n                                <i className=\"fa fa-star\" /><i className=\"fa fa-star\" /><i className=\"fa fa-star\" />\r\n                                <i className=\"fa fa-star\" />\r\n                            </div>\r\n                        </div>\r\n                        <div className=\"rate-description\">Exceeds expectations: Significant performance and exceeded expectations.\r\n                            The quality of work overall was excellent and was able to deal with big problems with minimal direction.\r\n                            </div>\r\n                    </div>\r\n                    <div className=\"rate-item\">\r\n                        <div className=\"rate-star\">\r\n                            <span>Excellent:5</span>\r\n                            <div className=\"star-block\">\r\n                                <i className=\"fa fa-star\" /><i className=\"fa fa-star\" /><i className=\"fa fa-star\" />\r\n                                <i className=\"fa fa-star\" /><i className=\"fa fa-star\" />\r\n                            </div>\r\n                        </div>\r\n                        <div className=\"rate-description\">\r\n                            Exceptional: The most outstanding performance and far exceeded expectations due to exceptionally high quality of work.\r\n                            Made a superior contribution in support team/department objectives.\r\n                            </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { Component, Fragment } from 'react';\r\nimport ReactDOM from 'react-dom';\r\nimport moment from 'moment';\r\nimport axios from 'axios';\r\nimport { OverlayTrigger } from 'react-bootstrap';\r\n\r\nimport { axiosError, resolveClientUrl } from '../../../common-functions';\r\nimport getResource from '../../../resourceHelper';\r\nimport NexPanel from '../../../shared/components/NexPanel';\r\nimport Description from '../../probation/Description';\r\nimport HRM from '../../probation/HRM';\r\nimport EvaluationDetailTooltip from '../../probation/EvaluationDetailTooltip';\r\n\r\nexport default class Detail extends Component {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            employeeId: document.getElementById('employee-id').value,\r\n            probationer: null,\r\n            evaluationDetails: []\r\n        };\r\n    }\r\n\r\n    componentDidMount() {\r\n        const promises = [\r\n            axios(resolveClientUrl('ProbationReport/GetByEmployeeId'), {\r\n                params: {\r\n                    id: this.state.employeeId\r\n                }\r\n            })\r\n        ];\r\n\r\n        Promise.all(promises)\r\n            .then(([response]) => {\r\n                const probationer = response.data.probationer;\r\n                probationer.joinedDate = moment(probationer.joinedDate);\r\n                probationer.avatar = `${document.getElementById('image-url').value}/${response.data.probationer.code}.jpg`;\r\n\r\n                this.setState({\r\n                    evaluationDetails: response.data.details,\r\n                    probationer: probationer,\r\n                    hrm: response.data.hrm\r\n                });\r\n            }).catch(axiosError);\r\n    }\r\n\r\n    renderKPI = (kpi, index) => {\r\n        return (\r\n            <tr key={kpi.kpiId}>\r\n                <td>{kpi.kpiGroupId}-{index + 1}. {kpi.kpiName}</td>\r\n                <td className=\"text-center\"><strong>{kpi.selfPoint}</strong></td>\r\n                <td className=\"text-center\"><strong>{kpi.evaluatorPoint}</strong></td>\r\n            </tr>\r\n        );\r\n    };\r\n\r\n    renderKPIGroup = (kpiGroup, index) => {\r\n        return (\r\n            <Fragment key={kpiGroup.kpiGroupId}>\r\n                <tr className=\"group-row\">\r\n                    <td>{index + 1}. {kpiGroup.name}</td>\r\n                    <td className=\"text-center\">{getResource('Employee')}</td>\r\n                    <td className=\"text-center\">{getResource('Evaluator')}</td>\r\n                </tr>\r\n                {kpiGroup.details.map(this.renderKPI)}\r\n            </Fragment>\r\n        );\r\n    };\r\n\r\n    renderPerformanceResult = isQualified => {\r\n        return isQualified !== null &&\r\n            <span className={isQualified ? 'passed' : 'failed'}>\r\n                {isQualified ? 'Passed' : 'Failed'}\r\n            </span>;\r\n    };\r\n\r\n    render() {\r\n        if (this.state.probationer) {\r\n            const probationerDetail = this.state.probationer;\r\n            return (\r\n                <div className=\"row\">\r\n                    <div className=\"main-content\">\r\n                        <NexPanel title=\"PERFORMANCE REVIEW: SKILLS AND ABILITIE\">\r\n                            <Description employeeInfo={probationerDetail} />\r\n                        </NexPanel>\r\n\r\n                        <NexPanel title=\"HRM System\" enable={false}>\r\n                            <HRM hrm={this.state.hrm} />\r\n                        </NexPanel>\r\n                        <NexPanel title=\"Performance Result\">\r\n                            <div className=\"result-table\">\r\n                                <table className=\"table table-bordered table-striped\">\r\n                                    <tbody>\r\n                                        <tr className=\"group-row\">\r\n                                            <td><span>A. RESULT</span></td>\r\n                                            <td colSpan=\"3\" />\r\n                                        </tr>\r\n                                        <tr>\r\n                                            <td className=\"text-center text-title\">{getResource('Self')}</td>\r\n                                            <td className=\"text-center text-title\">{getResource('Score')}</td>\r\n                                            <td className=\"text-center text-score\">{probationerDetail.selfScore && `${probationerDetail.selfScore} pts`}</td>\r\n                                            <td className=\"comment-cell comment-text\">\r\n                                                <p>{probationerDetail.selfComment}</p>\r\n                                            </td>\r\n                                        </tr>\r\n                                        <tr>\r\n                                            <td className=\"text-center text-title\" rowSpan={probationerDetail.canViewEvaluatorResult ? 2 : 1}>\r\n                                                {getResource('Evaluator')}\r\n                                                <div>({probationerDetail.evaluatorNickName})</div>\r\n                                            </td>\r\n                                            <td className=\"text-center text-title\">{getResource('Score')}</td>\r\n                                            <td className=\"text-center text-score\">{probationerDetail.evaluatorScore && `${probationerDetail.evaluatorScore} pts`}</td>\r\n                                            <td className=\"comment-cell comment-text\" rowSpan={probationerDetail.canViewEvaluatorResult ? 2 : 1}>\r\n                                                <p>{probationerDetail.evaluatorComment}</p>\r\n                                            </td>\r\n                                        </tr>\r\n                                        {\r\n                                            probationerDetail.canViewEvaluatorResult &&\r\n                                            <tr>\r\n                                                <td className=\"text-center text-title\">{getResource('Result')}</td>\r\n                                                <td className=\"text-center text-score\">\r\n                                                    {this.renderPerformanceResult(probationerDetail.isQualifiedByEvaluator)}\r\n                                                </td>\r\n                                            </tr>\r\n                                        }\r\n                                        <tr>\r\n                                            <td className=\"text-center text-title\">\r\n                                                {getResource('Reviewer')}\r\n                                                <div>({probationerDetail.reviewerNickName})</div>\r\n                                            </td>\r\n                                            <td className=\"text-center text-title\">{getResource('FinalResult')}</td>\r\n                                            <td className=\"text-center text-score\">\r\n                                                {this.renderPerformanceResult(probationerDetail.isQualified)}\r\n                                            </td>\r\n                                            <td className=\"comment-cell comment-text\">\r\n                                                <p>{probationerDetail.reviewerComment}</p>\r\n                                            </td>\r\n                                        </tr>\r\n                                    </tbody>\r\n                                </table>\r\n                            </div>\r\n                            <table className=\"table table-bordered table-striped\">\r\n                                <tbody>\r\n                                    <tr className=\"group-row\">\r\n                                        <td colSpan=\"3\">\r\n                                            B. DETAILS\r\n                                            <OverlayTrigger placement=\"bottom\" overlay={EvaluationDetailTooltip}>\r\n                                                <i className=\"icon-info\" />\r\n                                            </OverlayTrigger>\r\n                                        </td>\r\n                                    </tr>\r\n                                    {this.state.evaluationDetails.map(this.renderKPIGroup)}\r\n                                    <tr className=\"score\">\r\n                                        <td className=\"text-center\"><strong>{getResource('Score')}</strong></td>\r\n                                        <td className=\"text-center\">\r\n                                            {\r\n                                                probationerDetail.selfScore &&\r\n                                                <span className=\"score-badge\"><span>{probationerDetail.selfScore}</span>/100 pts</span>\r\n                                            }\r\n                                        </td>\r\n                                        <td className=\"text-center\">\r\n                                            {\r\n                                                probationerDetail.evaluatorScore &&\r\n                                                <span className=\"score-badge\"><span>{probationerDetail.evaluatorScore}</span>/100 pts</span>\r\n                                            }\r\n                                        </td>\r\n                                    </tr>\r\n                                </tbody>\r\n                            </table>\r\n                        </NexPanel>\r\n\r\n                        <a className=\"btn btn-primary\" href={resolveClientUrl('ProbationReport/Index')}>Back</a>\r\n                    </div >\r\n                </div >\r\n            );\r\n        }\r\n\r\n        return <Fragment />;\r\n    }\r\n}\r\n\r\nReactDOM.render(<Detail />, document.getElementById('probation-report-detail-wrapper'));"],"sourceRoot":""}
